package com.nexushr.controller; import com.nexushr.dto.AuthDtos.*; import com.nexushr.service.AuthService; import org.springframework.web.bind.annotation.*; import jakarta.validation.Valid; import java.util.Map; @RestController @RequestMapping("/auth") public class AuthController {final AuthService s;public AuthController(AuthService s){this.s=s;} @PostMapping("/login") public AuthResponse login(@RequestBody LoginRequest r){return s.login(r);} @PostMapping("/register") public Map<String,Object> register(@RequestBody RegisterRequest r){var u=s.register(r);return Map.of("id",u.getId(),"email",u.getEmail(),"role",u.getRole());}}
